mapper.select:
SELECT t.id, t.code, t.name, t.description, t.status, t.created_by AS createdBy, t.created_date AS createdDate, t.updated_by AS updatedBy, t.updated_date AS updatedDate FROM tenants t WHERE t.deleted = false
AND (t.code ILIKE '%' || #{keyword} || '%' OR t.name ILIKE '%' || #{keyword} || '%' OR t.description ILIKE '%' || #{keyword} || '%')
ORDER BY t.created_date DESC LIMIT #{limit} OFFSET #{offset}
